  p::need(c.at("schema")=="CANONICAL_NORM_ESTIMATED_TARGET_V1"&&c.at("process")==plan.at("source_process")&&c.at("native_launch_binding").at("process")==c.at("process")&&c.at("native_launch_binding").at("source_launch_key")==c.at("source_launch_key"),"canonical current argument identity");
