 U address(const J&c,U cta,const Formula&r,U lane)const{
  p::need(cta<p::natural(c.at("grid")[0])&&lane<32&&r.warp<16&&r.width==16,"formula coordinate domain");U stride=r.role=="weight"?0:p::natural(c.at("arguments").at(r.role+"_stride_elements"));U offset=p::multiply(2,p::add(p::multiply(cta,stride),8*(32*r.warp+lane)));U a=p::add(p::natural(c.at("arguments").at(r.role)),offset);const auto&o=c.at("objects").at(r.role);p::need(a>=p::natural(o.at("pointer"))&&p::add(a,16)<=p::natural(o.at("end_exclusive")),"generated current call extent");return a;
 }
 J service_map()const{std::vector<std::pair<U,U>>spans;for(auto*c:calls)for(auto role:{"input","output","weight"}){const auto&o=c->at("objects").at(role);U lo=p::natural(o.at("pointer")),hi=p::natural(o.at("end_exclusive"));p::need(hi<=UINT64_MAX-127,"aligned map bound");spans.emplace_back(lo/128*128,(hi+127)/128*128);}std::sort(spans.begin(),spans.end());std::vector<std::pair<U,U>>merged;for(auto x:spans){if(!merged.empty()&&x.first<=merged.back().second)merged.back().second=std::max(x.second,merged.back().second);else merged.push_back(x);}J rows=J::array();U off=0;for(auto[lo,hi]:merged){rows.push_back({{"source_base",lo},{"bytes",hi-lo},{"service_base",off}});off=p::add(off,hi-lo);}return {{"schema","SG_SOURCE_TO_SERVICE_MAP_V1"},{"qualification","PACKED_SOURCE_GENERATED_128B_LINES_NOT_PHYSICAL_HARDWARE_ADDRESSES"},{"spans",rows}};}
